  "about_items": [
    {
      "n": "#83·35",
      "text": "A soft beige knit dress with a classic round neck and long sleeves, falling just above the knee. Its gentle drape and subtle texture create a warm, welcoming silhouette that feels perfect for an autumn evening."
    },
    {
      "n": "#207·20",
      "text": "A delicate light blue mesh cardigan with wide, flowing sleeves and pearl-embellished buttons down the front. The airy fabric adds a touch of romance without heaviness, letting it layer effortlessly over your dress."
    },
    {
      "n": "#342·39",
      "text": "A brown ribbed knit belt with a sleek, minimalist buckle that wraps snugly around your waist. Its stretchy fabric hugs your curves gently while defining your silhouette with a modern, clean line."
    },
    {
      "n": "#15·22",
      "text": "Pointed-toe pumps in soft grey suede with a slender heel, offering height and sophistication without sacrificing comfort. The muted tone grounds the outfit and adds quiet confidence to your step."
    },
    {
      "n": "#356·07",
      "text": "A structured beige woven clutch with black leather trim and a bold gold U-shaped clasp that opens the flap for easy access. Its geometric texture adds subtle interest without overwhelming the simplicity of your look."
    }
  ]
}
